from scipy.optimize import brentq
def q_nonlocal(a):
    roots=roots_deriv(a, 3*np.pi)
    mins=[r for r in roots if np.cos(r)+a*a>0]
    if not mins:
        return np.inf
    r=mins[0]
    return math.sqrt(d2_dim(r,a))/2

f=lambda a: q_nonlocal(a)-(1+a*a)
# find bracket
for lo,hi in zip(np.linspace(.3,.5,20)[:-1],np.linspace(.3,.5,20)[1:]):
    if np.isfinite(q_nonlocal(lo)) and np.isfinite(q_nonlocal(hi)):
        if f(lo)*f(hi)<0:
            root=brentq(f,lo,hi); print(root,q_nonlocal(root),1+root**2)

