    "positive_rays_plus_origin": "4-simplex",
    "full_plus_minus_axes": "16-cell"
  },
  "lagrangian": {
    "mechanics": "L_w(q,q_w,w) = (1/c) L(q, c q_w, w/c)",
    "momentum": "p_w = p",
    "hamiltonian": "H_w = H/c",
